#!/usr/bin/env node
/**
 * Regenerates src/lib/leadership/dashboard-html.ts from Index.html, so the page
 * the hub serves is always the page in this folder. Run after editing Index.html:
 *   node integrations/instructional-leadership/build-template.mjs
 * A unit test fails if the generated file is out of date.
 */
import { readFileSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const here = dirname(fileURLToPath(import.meta.url));
const html = readFileSync(join(here, "Index.html"), "utf8");
const out = join(here, "../../src/lib/leadership/dashboard-html.ts");
writeFileSync(
  out,
  `// Generated by integrations/instructional-leadership/build-template.mjs from Index.html. Do not edit.\nexport const DASHBOARD_HTML = ${JSON.stringify(html)};\n`,
);
console.log(`wrote ${out}`);
